SELECT DISTINCT "OBTN"."ItemCode","OBTN"."ItemName","OBTN"."DistNumber" as 'Batch Number',"OBTQ"."Quantity",Coalesce((SELECT sum(r."Quantity")  FROM "BEAS_RESERVATION_LINE" r WHERE r."ItemCode"="OBTN"."ItemCode" and r."RESERVATIONTYPE"='S' and r."WhsCode"="OBTQ"."WhsCode" and r."BatchNum"="OBTN"."DistNumber"),0) as "RESERVATION", "OBTQ"."WhsCode" as 'Warehouse', "OITM"."InvntryUom" as 'UoM', "OBTN"."MnfSerial" as 'Manufacture Serial', "OINM"."DocDate" FROM "OBTN" INNER JOIN "OINM" on "OINM"."ItemCode"="OBTN"."ItemCode"INNER JOIN "OBTQ" on "OBTQ"."ItemCode"="OBTN"."ItemCode" and "OBTQ"."SysNumber"="OBTN"."SysNumber" INNER JOIN "OWHS" on "OWHS"."WhsCode"="OBTQ"."WhsCode" INNER JOIN "OITM" on "OITM"."ItemCode"="OBTN"."ItemCode" LEFT OUTER JOIN "OLCT" on "OLCT"."Code" = "OWHS"."Location" WHERE "OBTQ"."Quantity" <> 0ORDER BY DocDate DESC